function implPrompt(t) {
  return `${PREAMBLE}

YOUR TASK (${t.key}). OWNED PATHS: ${t.owned.join(', ')}.
Most relevant research reports: ${t.reports.join(', ')} (in ${REPORTS}/).

${t.spec}

Finish by returning the structured report (files, exact exported API with signatures, test counts, the literal verification results, caveats, foundation_requests).`
}

function reviewPrompt(t, impl) {
  return `${PREAMBLE}

You are the INDEPENDENT REVIEWER for module "${t.key}" (OWNED PATHS: ${t.owned.join(', ')}). Another agent just implemented it; you now own these paths and must find and FIX defects. Be adversarial: assume there are bugs.

The implementer's report:
${JSON.stringify(impl, null, 1).slice(0, 12000)}

The original specification the module must satisfy:
${t.spec}

Review checklist — verify each against the code, the research reports (${t.reports.join(', ')} in ${REPORTS}/) and the real fixtures in tests/fixtures/:
1. Real-data integrity: no fabricated/zero-filled/defaulted market values; missing upstream fields stay undefined; no placeholder numbers; 'freshness' labels honest (indexed data never 'realtime'/'stream').
2. Units: ms vs seconds (Candle.time seconds only), decimal-adjusted amounts, 0-100 percentages (fractions converted), SOL vs lamports, raw string amounts parsed safely (BigInt where > 2^53).
3. Upstream quirks from the report's gotchas are handled (batch limits and silent truncation, omitted-vs-null fields, newest-first lists, prefixed ids, string numbers, error body shapes, 429 semantics).
4. Contract compliance with src/lib/core/providers.ts and types.ts (method names, return Sourced<T>, provider ids), and with the spec's exported names/signatures (other modules depend on them).
5. Errors: ProviderError codes correct; keys never in messages (label used); aborts propagate; empty arrays only for genuinely empty upstream data.
6. Isomorphism rules: isomorphic adapters have no 'server-only'/Node imports/process.env; keyed adapters DO import 'server-only'.
7. Tests: meaningful assertions on real fixtures (not tautologies), compile under strict TS, cover failure paths.
Fix every defect you find directly in the owned files (add tests that would have caught it). Do not rewrite working code for style. Then run from the repo root: npx tsc --noEmit (fix all errors in your paths), npx eslint <paths>, npx vitest run <paths> — all clean for your paths.
Return the structured review (defects_found with fixed flags, final exported API, verification results, remaining_risks, foundation_requests).`
}

const results = await pipeline(
  TASKS,
  (t) => agent(implPrompt(t), { label: `impl:${t.key}`, phase: 'Implement', schema: REPORT_SCHEMA }),
  (impl, t) => agent(reviewPrompt(t, impl), { label: `review:${t.key}`, phase: 'Review', schema: REVIEW_SCHEMA }).then((review) => ({ key: t.key, impl, review })),
)
return results.filter(Boolean)
